"""Editable, source-backed user-flow descriptions for the documentation guide."""
def node(id,label,sub,actor,route,state,rules,tests,kind='',pos=None):
    d=dict(id=id,label=label,sub=sub,actor=actor,route=route,state=state,rules=rules,tests=tests.split(),kind=kind)
    if pos:d.update(x=pos[0],y=pos[1])
    return d
def edge(a,b,label='',**kw):return dict(from_=a,to=b,label=label,**kw)
def flow(id,title,description,nodes,edges):
    for i,n in enumerate(nodes):
        row,col=divmod(i,3)
        if row%2:col=2-col
        n.setdefault('x',30+330*col);n.setdefault('y',30+150*row)
    for e in edges:e['from']=e.pop('from_')
    height=max(n['y'] for n in nodes)+125
    for e in edges:
        if e.get('path'):height=max(height,e.get('maxY',height)+20)
    return dict(id=id,title=title,description=description,nodes=nodes,edges=edges,width=1000,height=height)

